```cpp
#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int liczba;
    int ile = 0;
    while (plik >> liczba) {
        string s = to_string(liczba);
        bool rosnacy = true;
        for (int i = 0; i < (int)s.length() - 1; i++) {
            if (s[i] >= s[i + 1]) {
                rosnacy = false;
                break;
            }
        }
        cout << liczba << ": cyfry [";
        for (int i = 0; i < (int)s.length(); i++) {
            if (i > 0) cout << ",";
            cout << s[i];
        }
        cout << "] -> " << (rosnacy ? "TAK" : "NIE") << endl;
        if (rosnacy) ile++;
    }
    cout << "Liczb z cyframi scisle rosnacymi: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Konwersja na string pozwala iterowac po cyfrach od lewej do prawej. Porownanie znakow `s[i] >= s[i+1]` jest poprawne, bo kody ASCII cyfr zachowuja porzadek.

